"use client";

import { useEffect, useMemo, useState } from "react";
import DashboardScaffold from "@/components/DashboardScaffold";
import WorkspaceShell from "@/components/workspace/WorkspaceShell";
import type { WorkspacePanelDescriptor } from "@/components/workspace/types";
import recoveryStyles from "@/app/hbx-recovery/page.module.css";
import { apiFetch } from "../_lib/api";
import { useRequireAuth } from "../_lib/useRequireAuth";

type WebsitePortal = {
  companyId: number | null;
  companyName: string | null;
  companySlug: string | null;
  configured: boolean;
  websiteEnabled: boolean;
  websitePublicUrl: string | null;
  websiteAdminUrl: string | null;
  websiteProjectId: string | null;
  websiteAdminEnabled: boolean;
  websiteLaunchMode: "public" | "admin";
  adminAllowed: boolean;
  launchTarget: "public" | "admin" | null;
  launchUrl: string | null;
  message: string | null;
};

type CurrentUserProfile = {
  id?: number | null;
  username?: string | null;
  role?: string | null;
  isSystemMaster?: boolean;
  company?: {
    id?: number | null;
    name?: string | null;
  } | null;
};

export default function WebsiteClientPage() {
  const hasToken = useRequireAuth();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [portal, setPortal] = useState<WebsitePortal | null>(null);
  const [currentUser, setCurrentUser] = useState<CurrentUserProfile | null>(null);

  async function loadData() {
    setLoading(true);
    setError(null);

    try {
      const [portalPayload, profilePayload] = await Promise.all([
        apiFetch<WebsitePortal>("/website/portal"),
        apiFetch<CurrentUserProfile>("/profile/current-user").catch(() => null),
      ]);
      setPortal(portalPayload);
      setCurrentUser(profilePayload);
    } catch (loadError) {
      const message =
        loadError instanceof Error ? loadError.message : "Falha ao abrir o modulo Website.";
      setError(message);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (hasToken !== true) return;
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasToken]);

  const websiteWorkspacePanels: WorkspacePanelDescriptor[] = useMemo(
    () => [
      {
        id: "website-launch",
        title: "Lançamento",
        description: "Abertura rápida do site público ou do admin disponível.",
        component: "websiteLaunchPanel",
        minimumWidth: 420,
        initialWidth: 620,
      },
      {
        id: "website-governance",
        title: "Governança",
        description: "Estado de habilitação, modo padrão e política de acesso.",
        component: "websiteGovernancePanel",
        minimumWidth: 320,
        maximumWidth: 480,
        initialWidth: 360,
      },
      {
        id: "website-links",
        title: "Links e Ações",
        description: "Links publicados, atalhos operacionais e recarga do portal.",
        component: "websiteLinksPanel",
        minimumWidth: 320,
        maximumWidth: 520,
        initialWidth: 360,
      },
    ],
    [],
  );

  const websiteWorkspaceComponents = useMemo(
    () => ({
      websiteLaunchPanel: () => (
        <div className={recoveryStyles.workspaceDockPanel}>
          <div className={recoveryStyles.workspaceDockPanelHeader}>
            <div>
              <strong>{portal?.launchUrl ? "Acesso pronto" : "Website indisponível"}</strong>
              <p className="text-sm text-muted">
                {portal?.message ||
                  "Abra o destino seguro da empresa sem sair do workspace HBX."}
              </p>
            </div>
            <span className={recoveryStyles.workspaceDockCounter}>
              {portal?.launchTarget === "admin" ? "ADMIN" : "SITE"}
            </span>
          </div>

          <section className="panel p-4 space-y-3">
            <div className="space-y-1">
              <p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted">
                Destino atual
              </p>
              <h3 className="text-xl font-semibold text-(--foreground)">
                {portal?.launchTarget === "admin" ? "Admin do Website" : "Site Público"}
              </h3>
            </div>

            <p className="text-sm text-muted">
              {portal?.launchUrl
                ? `O módulo detectou ${portal.launchTarget === "admin" ? "o admin" : "o site público"} disponível para ${portal.companyName || "sua empresa"}.`
                : "Nenhum destino de lançamento foi liberado para a empresa atual."}
            </p>

            <div className="flex flex-wrap gap-2">
              {portal?.launchUrl ? (
                <a className="btn btn-primary btn-sm" href={portal.launchUrl} target="_blank" rel="noreferrer">
                  Abrir destino liberado
                </a>
              ) : null}
              {portal?.websitePublicUrl ? (
                <a className="btn btn-secondary btn-sm" href={portal.websitePublicUrl} target="_blank" rel="noreferrer">
                  Site público
                </a>
              ) : null}
              {portal?.websiteAdminEnabled && portal?.websiteAdminUrl ? (
                <a className="btn btn-secondary btn-sm" href={portal.websiteAdminUrl} target="_blank" rel="noreferrer">
                  Abrir admin
                </a>
              ) : null}
            </div>
          </section>
        </div>
      ),
      websiteGovernancePanel: () => (
        <div className={recoveryStyles.workspaceDockPanel}>
          <div className={recoveryStyles.workspaceDockPanelHeader}>
            <div>
              <strong>Governança do módulo</strong>
              <p className="text-sm text-muted">Regras de acesso e configuração efetiva.</p>
            </div>
            <span className={recoveryStyles.workspaceDockCounter}>
              {portal?.configured ? "OK" : "OFF"}
            </span>
          </div>

          <section className="panel p-4 space-y-3">
            <div className="grid gap-2 text-sm text-muted">
              <p>Empresa: {portal?.companyName || currentUser?.company?.name || "-"}</p>
              <p>Configurado: {portal?.configured ? "Sim" : "Não"}</p>
              <p>Website habilitado: {portal?.websiteEnabled ? "Sim" : "Não"}</p>
              <p>Admin habilitado: {portal?.websiteAdminEnabled ? "Sim" : "Não"}</p>
              <p>Admin permitido para o usuário: {portal?.adminAllowed ? "Sim" : "Não"}</p>
              <p>Modo padrão: {portal?.websiteLaunchMode === "admin" ? "Admin" : "Público"}</p>
              <p>Projeto: {portal?.websiteProjectId || "-"}</p>
            </div>
          </section>
        </div>
      ),
      websiteLinksPanel: () => (
        <div className={recoveryStyles.workspaceDockPanel}>
          <div className={recoveryStyles.workspaceDockPanelHeader}>
            <div>
              <strong>Links e ações</strong>
              <p className="text-sm text-muted">Atalhos operacionais e recarga de contexto.</p>
            </div>
            <span className={recoveryStyles.workspaceDockCounter}>3</span>
          </div>

          <section className="panel p-4 space-y-3">
            <div className="grid gap-2 text-sm text-muted">
              <p>URL pública: {portal?.websitePublicUrl || "-"}</p>
              <p>URL admin: {portal?.websiteAdminUrl || "-"}</p>
              <p>Destino liberado: {portal?.launchUrl || "-"}</p>
            </div>

            <div className="flex flex-wrap gap-2">
              <button type="button" className="btn btn-secondary btn-sm" onClick={() => void loadData()}>
                Recarregar portal
              </button>
            </div>
          </section>
        </div>
      ),
    }),
    [currentUser?.company?.name, portal],
  );

  const createWebsiteWorkspaceLayout = (
    api: any,
    panels: Record<string, WorkspacePanelDescriptor>,
  ) => {
    api.addPanel({
      id: panels["website-launch"].id,
      title: panels["website-launch"].title,
      component: panels["website-launch"].component,
      minimumWidth: panels["website-launch"].minimumWidth,
      initialWidth: panels["website-launch"].initialWidth,
    });

    api.addPanel({
      id: panels["website-governance"].id,
      title: panels["website-governance"].title,
      component: panels["website-governance"].component,
      minimumWidth: panels["website-governance"].minimumWidth,
      maximumWidth: panels["website-governance"].maximumWidth,
      initialWidth: panels["website-governance"].initialWidth,
      position: { referencePanel: panels["website-launch"].id, direction: "right" },
    });

    api.addPanel({
      id: panels["website-links"].id,
      title: panels["website-links"].title,
      component: panels["website-links"].component,
      minimumWidth: panels["website-links"].minimumWidth,
      maximumWidth: panels["website-links"].maximumWidth,
      initialWidth: panels["website-links"].initialWidth,
      position: { referencePanel: panels["website-governance"].id, direction: "right" },
    });
  };

  if (hasToken === null) {
    return (
      <main className="app-shell">
        <div className="app-container">
          <div className="panel p-4 text-sm text-muted">Carregando modulo Website...</div>
        </div>
      </main>
    );
  }

  if (!hasToken) return null;

  return (
    <DashboardScaffold
      title="Website"
      description="Abrir o site da empresa e liberar acesso seguro ao admin quando permitido."
    >
      {error ? <div className="alert alert-error">{error}</div> : null}

      {loading ? (
        <div className="panel p-4 text-sm text-muted">Carregando configuracao do website...</div>
      ) : (
        <WorkspaceShell
          moduleLabel="Website"
          scope={{
            tenantId: String(currentUser?.company?.id || portal?.companyId || "tenant-default"),
            moduleKey: "website",
            role: String(currentUser?.role || "USER").toUpperCase(),
            userId: String(currentUser?.id || currentUser?.username || "anonymous"),
            isMaster: Boolean(currentUser?.isSystemMaster),
          }}
          panels={websiteWorkspacePanels}
          components={websiteWorkspaceComponents}
          createDefaultLayout={createWebsiteWorkspaceLayout}
          className={recoveryStyles.workspaceDockShell}
          toolbarSlot={
            <>
              <span className="badge">Empresa: {portal?.companyName || currentUser?.company?.name || "-"}</span>
              <span className="badge">Destino: {portal?.launchTarget === "admin" ? "Admin" : "Público"}</span>
            </>
          }
        />
      )}
    </DashboardScaffold>
  );
}
